-- OWASP Application Security Verification Standard 5.0.0 (framework
-- owasp-asvs-5.0), plus what every framework in 000078–000082 needs:
--
-- * Manual attestations (control_attestations): a project's record of how a
--   manual control is met — who, when, an evidence note, an optional link and
--   expiry. A live attestation scores the control as passing; an expired one
--   returns it to manual. One per (project, control); history is the audit log.
-- * Two match types: `category` (an open finding of a kind, e.g. every leaked
--   secret, whichever tool found it) and `severity` (an open finding of a
--   severity, for "resolve all high-risk vulnerabilities" requirements).
--
-- ASVS controls: each requirement that carries a CWE in OWASP's own ASVS 5.0
-- CWE mapping (5.0/mappings/v5.0.be_cwe_mapping.json joined through
-- mapping_v5.0.be_to_v5.0.0.yml) is measured at requirement level; the rest of a
-- section (and every documentation section) is one manual control at section
-- level. OWASP's mapping gives one CWE per requirement, often a parent class
-- scanners rarely emit, so a few requirements also take the child class
-- scanners report for exactly that requirement: V1.2.1 ← CWE-79/80 (XSS),
-- V3.4.2 ← 942 (CORS), V5.3.2 ← 22/23/36 (path traversal), V8.2.1 ← 862/863,
-- V11.4.1 ← 327/328, V11.4.2 ← 759/760/916, V16.5.1 ← 209. Three requirements
-- map to Xila signals: V13.3.1 (leaked secrets), V15.1.2 (SBOM), V15.2.1
-- (remediation SLA).
-- Requirement text © OWASP Foundation, CC BY-SA 4.0.

CREATE TABLE control_attestations (
    project_id        UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    control_id        UUID NOT NULL REFERENCES controls(id) ON DELETE CASCADE,
    note              TEXT NOT NULL CHECK (length(note) BETWEEN 1 AND 4000),
    evidence_url      TEXT NOT NULL DEFAULT '',
    attested_by       UUID REFERENCES users(id) ON DELETE SET NULL,
    attested_by_email TEXT NOT NULL DEFAULT '',
    attested_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at        TIMESTAMPTZ,
    PRIMARY KEY (project_id, control_id)
);
CREATE INDEX idx_control_attestations_control ON control_attestations (control_id);

ALTER TABLE control_mappings ADD COLUMN category TEXT, ADD COLUMN severity TEXT;
ALTER TABLE control_mappings DROP CONSTRAINT IF EXISTS control_mappings_match_type_check;
ALTER TABLE control_mappings ADD CONSTRAINT control_mappings_match_type_check
    CHECK (match_type IN ('cwe', 'rule', 'kev', 'sla', 'sbom', 'vex', 'category', 'severity'));

INSERT INTO frameworks (key, name, version, description)
VALUES ('owasp-asvs-5.0', 'OWASP ASVS', '5.0.0',
        'OWASP Application Security Verification Standard 5.0.0 (V1–V17). Requirements carrying a CWE in the official ASVS 5.0 CWE mapping are measured by findings in that weakness class; the rest are attested per section. Requirement text © OWASP Foundation, CC BY-SA 4.0, quoted verbatim in each description.');

INSERT INTO controls (framework_id, code, title, description, assessment)
SELECT fw.id, v.code, v.title, v.description, v.assessment
FROM frameworks fw
CROSS JOIN (VALUES
    ('V1.1.1', 'Input is decoded or unescaped into a canonical form only once, it is only…', 'Verify that input is decoded or unescaped into a canonical form only once, it is only decoded when encoded data in that form is expected, and that this is done before processing the input further, for example it is not performed after input validation or sanitization. (Level 2) Measured: open findings in CWE-174.', 'automatic'),
    ('V1.1.2', 'Application performs output encoding and escaping either as a final step…', 'Verify that the application performs output encoding and escaping either as a final step before being used by the interpreter for which it is intended or by the interpreter itself. (Level 2) Measured: open findings in CWE-116.', 'automatic'),
    ('V1.2', 'Injection Prevention', 'Section-level attestation for V1.2.3, V1.2.8 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V1.2.1', 'Output encoding for an HTTP response, HTML document, or XML document is…', 'Verify that output encoding for an HTTP response, HTML document, or XML document is relevant for the context required, such as encoding the relevant characters for HTML elements, HTML attributes, HTML comments, CSS, or HTTP header fields, to avoid changing the message or document structure. (Level 1) Measured: open findings in CWE-79, CWE-80, CWE-116.', 'automatic'),
    ('V1.2.2', 'When dynamically building URLs, untrusted data is encoded according to its…', 'Verify that when dynamically building URLs, untrusted data is encoded according to its context (e.g., URL encoding or base64url encoding for query or path parameters). Ensure that only safe URL protocols are permitted (e.g., disallow javascript: or data:). (Level 1) Measured: open findings in CWE-116.', 'automatic'),
    ('V1.2.4', 'Data selection or database queries (e.g., SQL, HQL, NoSQL, Cypher) use…', 'Verify that data selection or database queries (e.g., SQL, HQL, NoSQL, Cypher) use parameterized queries, ORMs, entity frameworks, or are otherwise protected from SQL Injection and other database injection attacks. This is also relevant when writing stored procedures. (Level 1) Measured: open findings in CWE-89.', 'automatic'),
    ('V1.2.5', 'Application protects against OS command injection and that operating system…', 'Verify that the application protects against OS command injection and that operating system calls use parameterized OS queries or use contextual command line output encoding. (Level 1) Measured: open findings in CWE-78.', 'automatic'),
    ('V1.2.6', 'Application protects against LDAP injection vulnerabilities, or that specific…', 'Verify that the application protects against LDAP injection vulnerabilities, or that specific security controls to prevent LDAP injection have been implemented. (Level 2) Measured: open findings in CWE-90.', 'automatic'),
    ('V1.2.7', 'Application is protected against XPath injection attacks by using query…', 'Verify that the application is protected against XPath injection attacks by using query parameterization or precompiled queries. (Level 2) Measured: open findings in CWE-643.', 'automatic'),
    ('V1.2.9', 'Application escapes special characters in regular expressions (typically using…', 'Verify that the application escapes special characters in regular expressions (typically using a backslash) to prevent them from being misinterpreted as metacharacters. (Level 2) Measured: open findings in CWE-624.', 'automatic'),
    ('V1.2.10', 'Application is protected against CSV and Formula Injection', 'Verify that the application is protected against CSV and Formula Injection. The application must follow the escaping rules defined in RFC 4180 sections 2.6 and 2.7 when exporting CSV content. Additionally, when exporting to CSV or other spreadsheet formats (such as XLS, XLSX, or ODF), special characters (including ''='', ''+'', ''-'', ''@'', ''\t'' (tab), and ''\0'' (null character)) must be escaped with a single quote if they appear as the first character in a field value. (Level 3) Measured: open findings in CWE-1236.', 'automatic'),
    ('V1.3', 'Sanitization', 'Section-level attestation for V1.3.9 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V1.3.1', 'All untrusted HTML input from WYSIWYG editors or similar is sanitized using a…', 'Verify that all untrusted HTML input from WYSIWYG editors or similar is sanitized using a well-known and secure HTML sanitization library or framework feature. (Level 1) Measured: open findings in CWE-116.', 'automatic'),
    ('V1.3.2', 'Application avoids the use of eval() or other dynamic code execution features…', 'Verify that the application avoids the use of eval() or other dynamic code execution features such as Spring Expression Language (SpEL). Where there is no alternative, any user input being included must be sanitized before being executed. (Level 1) Measured: open findings in CWE-95.', 'automatic'),
    ('V1.3.3', 'Data being passed to a potentially dangerous context is sanitized beforehand…', 'Verify that data being passed to a potentially dangerous context is sanitized beforehand to enforce safety measures, such as only allowing characters which are safe for this context and trimming input which is too long. (Level 2) Measured: open findings in CWE-138.', 'automatic'),
    ('V1.3.4', 'User-supplied Scalable Vector Graphics (SVG) scriptable content is validated…', 'Verify that user-supplied Scalable Vector Graphics (SVG) scriptable content is validated or sanitized to contain only tags and attributes (such as draw graphics) that are safe for the application, e.g., do not contain scripts and foreignObject. (Level 2) Measured: open findings in CWE-159.', 'automatic'),
    ('V1.3.5', 'Application sanitizes or disables user-supplied scriptable or expression…', 'Verify that the application sanitizes or disables user-supplied scriptable or expression template language content, such as Markdown, CSS or XSL stylesheets, BBCode, or similar. (Level 2) Measured: open findings in CWE-94.', 'automatic'),
    ('V1.3.6', 'Application protects against Server-side Request Forgery (SSRF) attacks, by…', 'Verify that the application protects against Server-side Request Forgery (SSRF) attacks, by validating untrusted data against an allowlist of protocols, domains, paths and ports and sanitizing potentially dangerous characters before using the data to call another service. (Level 2) Measured: open findings in CWE-918.', 'automatic'),
    ('V1.3.7', 'Application protects against template injection attacks by not allowing…', 'Verify that the application protects against template injection attacks by not allowing templates to be built based on untrusted input. Where there is no alternative, any untrusted input being included dynamically during template creation must be sanitized or strictly validated. (Level 2) Measured: open findings in CWE-94.', 'automatic'),
    ('V1.3.8', 'Application appropriately sanitizes untrusted input before use in Java Naming…', 'Verify that the application appropriately sanitizes untrusted input before use in Java Naming and Directory Interface (JNDI) queries and that JNDI is configured securely to prevent JNDI injection attacks. (Level 2) Measured: open findings in CWE-917.', 'automatic'),
    ('V1.3.10', 'Format strings which might resolve in an unexpected or malicious way when used…', 'Verify that format strings which might resolve in an unexpected or malicious way when used are sanitized before being processed. (Level 2) Measured: open findings in CWE-134.', 'automatic'),
    ('V1.3.11', 'Application sanitizes user input before passing to mail systems to protect…', 'Verify that the application sanitizes user input before passing to mail systems to protect against SMTP or IMAP injection. (Level 2) Measured: open findings in CWE-147.', 'automatic'),
    ('V1.3.12', 'Regular expressions are free from elements causing exponential backtracking…', 'Verify that regular expressions are free from elements causing exponential backtracking, and ensure untrusted input is sanitized to mitigate ReDoS or Runaway Regex attacks. (Level 3) Measured: open findings in CWE-1333.', 'automatic'),
    ('V1.4.1', 'Application uses memory-safe string, safer memory copy and pointer arithmetic…', 'Verify that the application uses memory-safe string, safer memory copy and pointer arithmetic to detect or prevent stack, buffer, or heap overflows. (Level 2) Measured: open findings in CWE-120.', 'automatic'),
    ('V1.4.2', 'Sign, range, and input validation techniques are used to prevent integer…', 'Verify that sign, range, and input validation techniques are used to prevent integer overflows. (Level 2) Measured: open findings in CWE-190.', 'automatic'),
    ('V1.4.3', 'Dynamically allocated memory and resources are released, and that references…', 'Verify that dynamically allocated memory and resources are released, and that references or pointers to freed memory are removed or set to null to prevent dangling pointers and use-after-free vulnerabilities. (Level 2) Measured: open findings in CWE-416.', 'automatic'),
    ('V1.5.1', 'Application configures XML parsers to use a restrictive configuration and that…', 'Verify that the application configures XML parsers to use a restrictive configuration and that unsafe features such as resolving external entities are disabled to prevent XML eXternal Entity (XXE) attacks. (Level 1) Measured: open findings in CWE-611.', 'automatic'),
    ('V1.5.2', 'Deserialization of untrusted data enforces safe input handling, such as using…', 'Verify that deserialization of untrusted data enforces safe input handling, such as using an allowlist of object types or restricting client-defined object types, to prevent deserialization attacks. Deserialization mechanisms that are explicitly defined as insecure must not be used with untrusted input. (Level 2) Measured: open findings in CWE-502.', 'automatic'),
    ('V1.5.3', 'Different parsers used in the application for the same data type (e.g., JSON…', 'Verify that different parsers used in the application for the same data type (e.g., JSON parsers, XML parsers, URL parsers), perform parsing in a consistent way and use the same character encoding mechanism to avoid issues such as JSON Interoperability vulnerabilities or different URI or file parsing behavior being exploited in Remote File Inclusion (RFI) or Server-side Request Forgery (SSRF) attacks. (Level 3) Measured: open findings in CWE-436.', 'automatic'),
    ('V2.1', 'Validation and Business Logic Documentation', 'Section-level attestation for V2.1.1, V2.1.2, V2.1.3 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V2.2.1', 'Input is validated to enforce business or functional expectations for that input', 'Verify that input is validated to enforce business or functional expectations for that input. This should either use positive validation against an allow list of values, patterns, and ranges, or be based on comparing the input to an expected structure and logical limits according to predefined rules. For L1, this can focus on input which is used to make specific business or security decisions. For L2 and up, this should apply to all input. (Level 1) Measured: open findings in CWE-20.', 'automatic'),
    ('V2.2.2', 'Application is designed to enforce input validation at a trusted service layer', 'Verify that the application is designed to enforce input validation at a trusted service layer. While client-side validation improves usability and should be encouraged, it must not be relied upon as a security control. (Level 1) Measured: open findings in CWE-602.', 'automatic'),
    ('V2.2.3', 'Application ensures that combinations of related data items are reasonable…', 'Verify that the application ensures that combinations of related data items are reasonable according to the pre-defined rules. (Level 2) Measured: open findings in CWE-20.', 'automatic'),
    ('V2.3', 'Business Logic Security', 'Section-level attestation for V2.3.2, V2.3.3, V2.3.4, V2.3.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V2.3.1', 'Application will only process business logic flows for the same user in the…', 'Verify that the application will only process business logic flows for the same user in the expected sequential step order and without skipping steps. (Level 1) Measured: open findings in CWE-841.', 'automatic'),
    ('V2.4.1', 'Anti-automation controls are in place to protect against excessive calls to…', 'Verify that anti-automation controls are in place to protect against excessive calls to application functions that could lead to data exfiltration, garbage-data creation, quota exhaustion, rate-limit breaches, denial-of-service, or overuse of costly resources. (Level 2) Measured: open findings in CWE-770.', 'automatic'),
    ('V2.4.2', 'Business logic flows require realistic human timing, preventing excessively…', 'Verify that business logic flows require realistic human timing, preventing excessively rapid transaction submissions. (Level 3) Measured: open findings in CWE-799.', 'automatic'),
    ('V3.1', 'Web Frontend Security Documentation', 'Section-level attestation for V3.1.1 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V3.2', 'Unintended Content Interpretation', 'Section-level attestation for V3.2.1, V3.2.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V3.2.3', 'Application avoids DOM clobbering when using client-side JavaScript by…', 'Verify that the application avoids DOM clobbering when using client-side JavaScript by employing explicit variable declarations, performing strict type checking, avoiding storing global variables on the document object, and implementing namespace isolation. (Level 3) Measured: open findings in CWE-79.', 'automatic'),
    ('V3.3', 'Cookie Setup', 'Section-level attestation for V3.3.3, V3.3.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V3.3.1', 'Cookies have the ''Secure'' attribute set, and if the ''\__Host-'' prefix is not…', 'Verify that cookies have the ''Secure'' attribute set, and if the ''\__Host-'' prefix is not used for the cookie name, the ''__Secure-'' prefix must be used for the cookie name. (Level 1) Measured: open findings in CWE-614.', 'automatic'),
    ('V3.3.2', 'Each cookie''s ''SameSite'' attribute value is set according to the purpose of…', 'Verify that each cookie''s ''SameSite'' attribute value is set according to the purpose of the cookie, to limit exposure to user interface redress attacks and browser-based request forgery attacks, commonly known as cross-site request forgery (CSRF). (Level 2) Measured: open findings in CWE-1275.', 'automatic'),
    ('V3.3.4', 'If the value of a cookie is not meant to be accessible to client-side scripts…', 'Verify that if the value of a cookie is not meant to be accessible to client-side scripts (such as a session token), the cookie must have the ''HttpOnly'' attribute set and the same value (e. g. session token) must only be transferred to the client via the ''Set-Cookie'' header field. (Level 2) Measured: open findings in CWE-1004.', 'automatic'),
    ('V3.4', 'Browser Security Mechanism Headers', 'Section-level attestation for V3.4.3, V3.4.7, V3.4.8 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V3.4.1', 'A Strict-Transport-Security header field is included on all responses to…', 'Verify that a Strict-Transport-Security header field is included on all responses to enforce an HTTP Strict Transport Security (HSTS) policy. A maximum age of at least 1 year must be defined, and for L2 and up, the policy must apply to all subdomains as well. (Level 1) Measured: open findings in CWE-523.', 'automatic'),
    ('V3.4.2', 'Cross-Origin Resource Sharing (CORS) Access-Control-Allow-Origin header field…', 'Verify that the Cross-Origin Resource Sharing (CORS) Access-Control-Allow-Origin header field is a fixed value by the application, or if the Origin HTTP request header field value is used, it is validated against an allowlist of trusted origins. When ''Access-Control-Allow-Origin: *'' needs to be used, verify that the response does not include any sensitive information. (Level 1) Measured: open findings in CWE-183, CWE-942.', 'automatic'),
    ('V3.4.4', 'All HTTP responses contain an ''X-Content-Type-Options: nosniff'' header field', 'Verify that all HTTP responses contain an ''X-Content-Type-Options: nosniff'' header field. This instructs browsers not to use content sniffing and MIME type guessing for the given response, and to require the response''s Content-Type header field value to match the destination resource. For example, the response to a request for a style is only accepted if the response''s Content-Type is ''text/css''. This also enables the use of the Cross-Origin Read Blocking (CORB) functionality by the browser. (Level 2) Measured: open findings in CWE-116.', 'automatic'),
    ('V3.4.5', 'Application sets a referrer policy to prevent leakage of technically sensitive…', 'Verify that the application sets a referrer policy to prevent leakage of technically sensitive data to third-party services via the ''Referer'' HTTP request header field. This can be done using the Referrer-Policy HTTP response header field or via HTML element attributes. Sensitive data could include path and query data in the URL, and for internal non-public applications also the hostname. (Level 2) Measured: open findings in CWE-116.', 'automatic'),
    ('V3.4.6', 'Web application uses the frame-ancestors directive of the…', 'Verify that the web application uses the frame-ancestors directive of the Content-Security-Policy header field for every HTTP response to ensure that it cannot be embedded by default and that embedding of specific resources is allowed only when necessary. Note that the X-Frame-Options header field, although supported by browsers, is obsolete and may not be relied upon. (Level 2) Measured: open findings in CWE-1021.', 'automatic'),
    ('V3.5', 'Browser Origin Separation', 'Section-level attestation for V3.5.6, V3.5.7, V3.5.8 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V3.5.1', 'If the application does not rely on the CORS preflight mechanism to prevent…', 'Verify that, if the application does not rely on the CORS preflight mechanism to prevent disallowed cross-origin requests to use sensitive functionality, these requests are validated to ensure they originate from the application itself. This may be done by using and validating anti-forgery tokens or requiring extra HTTP header fields that are not CORS-safelisted request-header fields. This is to defend against browser-based request forgery attacks, commonly known as cross-site request forgery (CSRF). (Level 1) Measured: open findings in CWE-352.', 'automatic'),
    ('V3.5.2', 'If the application relies on the CORS preflight mechanism to prevent…', 'Verify that, if the application relies on the CORS preflight mechanism to prevent disallowed cross-origin use of sensitive functionality, it is not possible to call the functionality with a request which does not trigger a CORS-preflight request. This may require checking the values of the ''Origin'' and ''Content-Type'' request header fields or using an extra header field that is not a CORS-safelisted header-field. (Level 1) Measured: open findings in CWE-346.', 'automatic'),
    ('V3.5.3', 'HTTP requests to sensitive functionality use appropriate HTTP methods such as…', 'Verify that HTTP requests to sensitive functionality use appropriate HTTP methods such as POST, PUT, PATCH, or DELETE, and not methods defined by the HTTP specification as "safe" such as HEAD, OPTIONS, or GET. Alternatively, strict validation of the Sec-Fetch-* request header fields can be used to ensure that the request did not originate from an inappropriate cross-origin call, a navigation request, or a resource load (such as an image source) where this is not expected. (Level 1) Measured: open findings in CWE-650.', 'automatic'),
    ('V3.5.4', 'Separate applications are hosted on different hostnames to leverage the…', 'Verify that separate applications are hosted on different hostnames to leverage the restrictions provided by same-origin policy, including how documents or scripts loaded by one origin can interact with resources from another origin and hostname-based restrictions on cookies. (Level 2) Measured: open findings in CWE-668.', 'automatic'),
    ('V3.5.5', 'Messages received by the postMessage interface are discarded if the origin of…', 'Verify that messages received by the postMessage interface are discarded if the origin of the message is not trusted, or if the syntax of the message is invalid. (Level 2) Measured: open findings in CWE-346.', 'automatic'),
    ('V3.6.1', 'Client-side assets, such as JavaScript libraries, CSS, or web fonts, are only…', 'Verify that client-side assets, such as JavaScript libraries, CSS, or web fonts, are only hosted externally (e.g., on a Content Delivery Network) if the resource is static and versioned and Subresource Integrity (SRI) is used to validate the integrity of the asset. If this is not possible, there should be a documented security decision to justify this for each resource. (Level 3) Measured: open findings in CWE-829.', 'automatic'),
    ('V3.7', 'Other Browser Security Considerations', 'Section-level attestation for V3.7.3, V3.7.4, V3.7.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V3.7.1', 'Application only uses client-side technologies which are still supported and…', 'Verify that the application only uses client-side technologies which are still supported and considered secure. Examples of technologies which do not meet this requirement include NSAPI plugins, Flash, Shockwave, ActiveX, Silverlight, NACL, or client-side Java applets. (Level 2) Measured: open findings in CWE-477.', 'automatic'),
    ('V3.7.2', 'Application will only automatically redirect the user to a different hostname…', 'Verify that the application will only automatically redirect the user to a different hostname or domain (which is not controlled by the application) where the destination appears on an allowlist. (Level 2) Measured: open findings in CWE-601.', 'automatic'),
    ('V4.1', 'Generic Web Service Security', 'Section-level attestation for V4.1.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V4.1.1', 'Every HTTP response with a message body contains a Content-Type header field…', 'Verify that every HTTP response with a message body contains a Content-Type header field that matches the actual content of the response, including the charset parameter to specify safe character encoding (e.g., UTF-8, ISO-8859-1) according to IANA Media Types, such as "text/", "/+xml" and "/xml". (Level 1) Measured: open findings in CWE-173.', 'automatic'),
    ('V4.1.3', 'Any HTTP header field used by the application and set by an intermediary…', 'Verify that any HTTP header field used by the application and set by an intermediary layer, such as a load balancer, a web proxy, or a backend-for-frontend service, cannot be overridden by the end-user. Example headers might include X-Real-IP, X-Forwarded-*, or X-User-ID. (Level 2) Measured: open findings in CWE-346.', 'automatic'),
    ('V4.1.4', 'Only HTTP methods that are explicitly supported by the application or its API…', 'Verify that only HTTP methods that are explicitly supported by the application or its API (including OPTIONS during preflight requests) can be used and that unused methods are blocked. (Level 3) Measured: open findings in CWE-749.', 'automatic'),
    ('V4.1.5', 'Per-message digital signatures are used to provide additional assurance on top…', 'Verify that per-message digital signatures are used to provide additional assurance on top of transport protections for requests or transactions which are highly sensitive or which traverse a number of systems. (Level 3) Measured: open findings in CWE-345.', 'automatic'),
    ('V4.2', 'HTTP Message Structure Validation', 'Section-level attestation for V4.2.3, V4.2.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V4.2.1', 'All application components (including load balancers, firewalls, and…', 'Verify that all application components (including load balancers, firewalls, and application servers) determine boundaries of incoming HTTP messages using the appropriate mechanism for the HTTP version to prevent HTTP request smuggling. In HTTP/1.x, if a Transfer-Encoding header field is present, the Content-Length header must be ignored per RFC 2616. When using HTTP/2 or HTTP/3, if a Content-Length header field is present, the receiver must ensure that it is consistent with the length of the DATA frames. (Level 2) Measured: open findings in CWE-444.', 'automatic'),
    ('V4.2.2', 'When generating HTTP messages, the Content-Length header field does not…', 'Verify that when generating HTTP messages, the Content-Length header field does not conflict with the length of the content as determined by the framing of the HTTP protocol, in order to prevent request smuggling attacks. (Level 3) Measured: open findings in CWE-400.', 'automatic'),
    ('V4.2.4', 'Application only accepts HTTP/2 and HTTP/3 requests where the header fields…', 'Verify that the application only accepts HTTP/2 and HTTP/3 requests where the header fields and values do not contain any CR (\r), LF (\n), or CRLF (\r\n) sequences, to prevent header injection attacks. (Level 3) Measured: open findings in CWE-113.', 'automatic'),
    ('V4.3', 'GraphQL', 'Section-level attestation for V4.3.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V4.3.1', 'A query allowlist, depth limiting, amount limiting, or query cost analysis is…', 'Verify that a query allowlist, depth limiting, amount limiting, or query cost analysis is used to prevent GraphQL or data layer expression Denial of Service (DoS) as a result of expensive, nested queries. (Level 2) Measured: open findings in CWE-770.', 'automatic'),
    ('V4.4.1', 'WebSocket over TLS (WSS) is used for all WebSocket connections', 'Verify that WebSocket over TLS (WSS) is used for all WebSocket connections. (Level 1) Measured: open findings in CWE-319.', 'automatic'),
    ('V4.4.2', 'During the initial HTTP WebSocket handshake, the Origin header field is…', 'Verify that, during the initial HTTP WebSocket handshake, the Origin header field is checked against a list of origins allowed for the application. (Level 2) Measured: open findings in CWE-346.', 'automatic'),
    ('V4.4.3', 'If the application''s standard session management cannot be used, dedicated…', 'Verify that, if the application''s standard session management cannot be used, dedicated tokens are being used for this, which comply with the relevant Session Management security requirements. (Level 2) Measured: open findings in CWE-331.', 'automatic'),
    ('V4.4.4', 'Dedicated WebSocket session management tokens are initially obtained or…', 'Verify that dedicated WebSocket session management tokens are initially obtained or validated through the previously authenticated HTTPS session when transitioning an existing HTTPS session to a WebSocket channel. (Level 2) Measured: open findings in CWE-319.', 'automatic'),
    ('V5.1', 'File Handling Documentation', 'Section-level attestation for V5.1.1 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V5.2.1', 'Application will only accept files of a size which it can process without…', 'Verify that the application will only accept files of a size which it can process without causing a loss of performance or a denial of service attack. (Level 1) Measured: open findings in CWE-400.', 'automatic'),
    ('V5.2.2', 'When the application accepts a file, either on its own or within an archive…', 'Verify that when the application accepts a file, either on its own or within an archive such as a zip file, it checks if the file extension matches an expected file extension and validates that the contents correspond to the type represented by the extension. This includes, but is not limited to, checking the initial ''magic bytes'', performing image re-writing, and using specialized libraries for file content validation. For L1, this can focus just on files which are used to make specific business or security decisions. For L2 and up, this must apply to all files being accepted. (Level 1) Measured: open findings in CWE-434.', 'automatic'),
    ('V5.2.3', 'Application checks compressed files (e.g., zip, gz, docx, odt) against maximum…', 'Verify that the application checks compressed files (e.g., zip, gz, docx, odt) against maximum allowed uncompressed size and against maximum number of files before uncompressing the file. (Level 2) Measured: open findings in CWE-409.', 'automatic'),
    ('V5.2.4', 'A file size quota and maximum number of files per user are enforced to ensure…', 'Verify that a file size quota and maximum number of files per user are enforced to ensure that a single user cannot fill up the storage with too many files, or excessively large files. (Level 3) Measured: open findings in CWE-770.', 'automatic'),
    ('V5.2.5', 'Application does not allow uploading compressed files containing symlinks…', 'Verify that the application does not allow uploading compressed files containing symlinks unless this is specifically required (in which case it will be necessary to enforce an allowlist of the files that can be symlinked to). (Level 3) Measured: open findings in CWE-61.', 'automatic'),
    ('V5.2.6', 'Application rejects uploaded images with a pixel size larger than the maximum…', 'Verify that the application rejects uploaded images with a pixel size larger than the maximum allowed, to prevent pixel flood attacks. (Level 3) Measured: open findings in CWE-400.', 'automatic'),
    ('V5.3.1', 'Files uploaded or generated by untrusted input and stored in a public folder…', 'Verify that files uploaded or generated by untrusted input and stored in a public folder, are not executed as server-side program code when accessed directly with an HTTP request. (Level 1) Measured: open findings in CWE-552.', 'automatic'),
    ('V5.3.2', 'When the application creates file paths for file operations, instead of…', 'Verify that when the application creates file paths for file operations, instead of user-submitted filenames, it uses internally generated or trusted data, or if user-submitted filenames or file metadata must be used, strict validation and sanitization must be applied. This is to protect against path traversal, local or remote file inclusion (LFI, RFI), and server-side request forgery (SSRF) attacks. (Level 1) Measured: open findings in CWE-22, CWE-23, CWE-36, CWE-73.', 'automatic'),
    ('V5.3.3', 'Server-side file processing, such as file decompression, ignores user-provided…', 'Verify that server-side file processing, such as file decompression, ignores user-provided path information to prevent vulnerabilities such as zip slip. (Level 3) Measured: open findings in CWE-23.', 'automatic'),
    ('V5.4', 'File Download', 'Section-level attestation for V5.4.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V5.4.1', 'Application validates or ignores user-submitted filenames, including in a…', 'Verify that the application validates or ignores user-submitted filenames, including in a JSON, JSONP, or URL parameter and specifies a filename in the Content-Disposition header field in the response. (Level 2) Measured: open findings in CWE-641.', 'automatic'),
    ('V5.4.3', 'Files obtained from untrusted sources are scanned by antivirus scanners to…', 'Verify that files obtained from untrusted sources are scanned by antivirus scanners to prevent serving of known malicious content. (Level 2) Measured: open findings in CWE-509.', 'automatic'),
    ('V6.1', 'Authentication Documentation', 'Section-level attestation for V6.1.1, V6.1.2, V6.1.3 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V6.2', 'Password Security', 'Section-level attestation for V6.2.8, V6.2.10, V6.2.12 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V6.2.1', 'User set passwords are at least 8 characters in length although a minimum of…', 'Verify that user set passwords are at least 8 characters in length although a minimum of 15 characters is strongly recommended. (Level 1) Measured: open findings in CWE-521.', 'automatic'),
    ('V6.2.2', 'Users can change their password', 'Verify that users can change their password. (Level 1) Measured: open findings in CWE-620.', 'automatic'),
    ('V6.2.3', 'Password change functionality requires the user''s current and new password', 'Verify that password change functionality requires the user''s current and new password. (Level 1) Measured: open findings in CWE-620.', 'automatic'),
    ('V6.2.4', 'Passwords submitted during account registration or password change are checked…', 'Verify that passwords submitted during account registration or password change are checked against an available set of, at least, the top 3000 passwords which match the application''s password policy, e.g. minimum length. (Level 1) Measured: open findings in CWE-521.', 'automatic'),
    ('V6.2.5', 'Passwords of any composition can be used, without rules limiting the type of…', 'Verify that passwords of any composition can be used, without rules limiting the type of characters permitted. There must be no requirement for a minimum number of upper or lower case characters, numbers, or special characters. (Level 1) Measured: open findings in CWE-521.', 'automatic'),
    ('V6.2.6', 'Password input fields use type=password to mask the entry', 'Verify that password input fields use type=password to mask the entry. Applications may allow the user to temporarily view the entire masked password, or the last typed character of the password. (Level 1) Measured: open findings in CWE-549.', 'automatic'),
    ('V6.2.7', '"paste" functionality, browser password helpers, and external password…', 'Verify that "paste" functionality, browser password helpers, and external password managers are permitted. (Level 1) Measured: open findings in CWE-521.', 'automatic'),
    ('V6.2.9', 'Passwords of at least 64 characters are permitted', 'Verify that passwords of at least 64 characters are permitted. (Level 2) Measured: open findings in CWE-521.', 'automatic'),
    ('V6.2.11', 'Documented list of context specific words is used to prevent easy to guess…', 'Verify that the documented list of context specific words is used to prevent easy to guess passwords being created. (Level 2) Measured: open findings in CWE-521.', 'automatic'),
    ('V6.3', 'General Authentication Security', 'Section-level attestation for V6.3.8 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V6.3.1', 'Controls to prevent attacks such as credential stuffing and password brute…', 'Verify that controls to prevent attacks such as credential stuffing and password brute force are implemented according to the application''s security documentation. (Level 1) Measured: open findings in CWE-307.', 'automatic'),
    ('V6.3.2', 'Default user accounts (e.g., "root", "admin", or "sa") are not present in the…', 'Verify that default user accounts (e.g., "root", "admin", or "sa") are not present in the application or are disabled. (Level 1) Measured: open findings in CWE-798.', 'automatic'),
    ('V6.3.3', 'Either a multi-factor authentication mechanism or a combination of…', 'Verify that either a multi-factor authentication mechanism or a combination of single-factor authentication mechanisms, must be used in order to access the application. For L3, one of the factors must be a hardware-based authentication mechanism which provides compromise and impersonation resistance against phishing attacks while verifying the intent to authenticate by requiring a user-initiated action (such as a button press on a FIDO hardware key or a mobile phone). Relaxing any of the considerations in this requirement requires a fully documented rationale and a comprehensive set of mitigating controls. (Level 2) Measured: open findings in CWE-308.', 'automatic'),
    ('V6.3.4', 'If the application includes multiple authentication pathways, there are no…', 'Verify that, if the application includes multiple authentication pathways, there are no undocumented pathways and that security controls and authentication strength are enforced consistently. (Level 2) Measured: open findings in CWE-306.', 'automatic'),
    ('V6.3.5', 'Users are notified of suspicious authentication attempts (successful or…', 'Verify that users are notified of suspicious authentication attempts (successful or unsuccessful). This may include authentication attempts from an unusual location or client, partially successful authentication (only one of multiple factors), an authentication attempt after a long period of inactivity or a successful authentication after several unsuccessful attempts. (Level 3) Measured: open findings in CWE-778.', 'automatic'),
    ('V6.3.6', 'Email is not used as either a single-factor or multi-factor authentication…', 'Verify that email is not used as either a single-factor or multi-factor authentication mechanism. (Level 3) Measured: open findings in CWE-304.', 'automatic'),
    ('V6.3.7', 'Users are notified after updates to authentication details, such as credential…', 'Verify that users are notified after updates to authentication details, such as credential resets or modification of the username or email address. (Level 3) Measured: open findings in CWE-778.', 'automatic'),
    ('V6.4.1', 'System generated initial passwords or activation codes are securely randomly…', 'Verify that system generated initial passwords or activation codes are securely randomly generated, follow the existing password policy, and expire after a short period of time or after they are initially used. These initial secrets must not be permitted to become the long term password. (Level 1) Measured: open findings in CWE-330.', 'automatic'),
    ('V6.4.2', 'Password hints or knowledge-based authentication (so-called "secret…', 'Verify that password hints or knowledge-based authentication (so-called "secret questions") are not present. (Level 1) Measured: open findings in CWE-640.', 'automatic'),
    ('V6.4.3', 'A secure process for resetting a forgotten password is implemented, that does…', 'Verify that a secure process for resetting a forgotten password is implemented, that does not bypass any enabled multi-factor authentication mechanisms. (Level 2) Measured: open findings in CWE-640.', 'automatic'),
    ('V6.4.4', 'If a multi-factor authentication factor is lost, evidence of identity proofing…', 'Verify that if a multi-factor authentication factor is lost, evidence of identity proofing is performed at the same level as during enrollment. (Level 2) Measured: open findings in CWE-308.', 'automatic'),
    ('V6.4.5', 'Renewal instructions for authentication mechanisms which expire are sent with…', 'Verify that renewal instructions for authentication mechanisms which expire are sent with enough time to be carried out before the old authentication mechanism expires, configuring automated reminders if necessary. (Level 3) Measured: open findings in CWE-287.', 'automatic'),
    ('V6.4.6', 'Administrative users can initiate the password reset process for the user, but…', 'Verify that administrative users can initiate the password reset process for the user, but that this does not allow them to change or choose the user''s password. This prevents a situation where they know the user''s password. (Level 3) Measured: open findings in CWE-620.', 'automatic'),
    ('V6.5.1', 'Lookup secrets, out-of-band authentication requests or codes, and time-based…', 'Verify that lookup secrets, out-of-band authentication requests or codes, and time-based one-time passwords (TOTPs) are only successfully usable once. (Level 2) Measured: open findings in CWE-308.', 'automatic'),
    ('V6.5.2', 'When being stored in the application''s backend, lookup secrets with less than…', 'Verify that, when being stored in the application''s backend, lookup secrets with less than 112 bits of entropy (19 random alphanumeric characters or 34 random digits) are hashed with an approved password storage hashing algorithm that incorporates a 32-bit random salt. A standard hash function can be used if the secret has 112 bits of entropy or more. (Level 2) Measured: open findings in CWE-330.', 'automatic'),
    ('V6.5.3', 'Lookup secrets, out-of-band authentication code, and time-based one-time…', 'Verify that lookup secrets, out-of-band authentication code, and time-based one-time password seeds, are generated using a Cryptographically Secure Pseudorandom Number Generator (CSPRNG) to avoid predictable values. (Level 2) Measured: open findings in CWE-310.', 'automatic'),
    ('V6.5.4', 'Lookup secrets and out-of-band authentication codes have a minimum of 20 bits…', 'Verify that lookup secrets and out-of-band authentication codes have a minimum of 20 bits of entropy (typically 4 random alphanumeric characters or 6 random digits is sufficient). (Level 2) Measured: open findings in CWE-330.', 'automatic'),
    ('V6.5.5', 'Out-of-band authentication requests, codes, or tokens, as well as time-based…', 'Verify that out-of-band authentication requests, codes, or tokens, as well as time-based one-time passwords (TOTPs) have a defined lifetime. Out of band requests must have a maximum lifetime of 10 minutes and for TOTP a maximum lifetime of 30 seconds. (Level 2) Measured: open findings in CWE-287.', 'automatic'),
    ('V6.5.6', 'Any authentication factor (including physical devices) can be revoked in case…', 'Verify that any authentication factor (including physical devices) can be revoked in case of theft or other loss. (Level 3) Measured: open findings in CWE-613.', 'automatic'),
    ('V6.5.7', 'Biometric authentication mechanisms are only used as secondary factors…', 'Verify that biometric authentication mechanisms are only used as secondary factors together with either something you have or something you know. (Level 3) Measured: open findings in CWE-308.', 'automatic'),
    ('V6.5.8', 'Time-based one-time passwords (TOTPs) are checked based on a time source from…', 'Verify that time-based one-time passwords (TOTPs) are checked based on a time source from a trusted service and not from an untrusted or client provided time. (Level 3) Measured: open findings in CWE-367.', 'automatic'),
    ('V6.6', 'Out-of-Band authentication mechanisms', 'Section-level attestation for V6.6.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V6.6.1', 'Authentication mechanisms using the Public Switched Telephone Network (PSTN)…', 'Verify that authentication mechanisms using the Public Switched Telephone Network (PSTN) to deliver One-time Passwords (OTPs) via phone or SMS are offered only when the phone number has previously been validated, alternate stronger methods (such as Time based One-time Passwords) are also offered, and the service provides information on their security risks to users. For L3 applications, phone and SMS must not be available as options. (Level 2) Measured: open findings in CWE-287.', 'automatic'),
    ('V6.6.2', 'Out-of-band authentication requests, codes, or tokens are bound to the…', 'Verify that out-of-band authentication requests, codes, or tokens are bound to the original authentication request for which they were generated and are not usable for a previous or subsequent one. (Level 2) Measured: open findings in CWE-287.', 'automatic'),
    ('V6.6.3', 'A code based out-of-band authentication mechanism is protected against brute…', 'Verify that a code based out-of-band authentication mechanism is protected against brute force attacks by using rate limiting. Consider also using a code with at least 64 bits of entropy. (Level 2) Measured: open findings in CWE-307.', 'automatic'),
    ('V6.7.1', 'Certificates used to verify cryptographic authentication assertions are stored…', 'Verify that the certificates used to verify cryptographic authentication assertions are stored in a way protects them from modification. (Level 3) Measured: open findings in CWE-320.', 'automatic'),
    ('V6.7.2', 'Challenge nonce is at least 64 bits in length, and statistically unique or…', 'Verify that the challenge nonce is at least 64 bits in length, and statistically unique or unique over the lifetime of the cryptographic device. (Level 3) Measured: open findings in CWE-330.', 'automatic'),
    ('V6.8', 'Authentication with an Identity Provider', 'Section-level attestation for V6.8.1, V6.8.2, V6.8.3, V6.8.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V7.1', 'Session Management Documentation', 'Section-level attestation for V7.1.1, V7.1.2, V7.1.3 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V7.2', 'Fundamental Session Management Security', 'Section-level attestation for V7.2.3, V7.2.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V7.2.1', 'Application performs all session token verification using a trusted, backend…', 'Verify that the application performs all session token verification using a trusted, backend service. (Level 1) Measured: open findings in CWE-603.', 'automatic'),
    ('V7.2.2', 'Application uses either self-contained or reference tokens that are…', 'Verify that the application uses either self-contained or reference tokens that are dynamically generated for session management, i.e. not using static API secrets and keys. (Level 1) Measured: open findings in CWE-798.', 'automatic'),
    ('V7.3', 'Session Timeout', 'Section-level attestation for V7.3.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V7.3.1', 'There is an inactivity timeout such that re-authentication is enforced…', 'Verify that there is an inactivity timeout such that re-authentication is enforced according to risk analysis and documented security decisions. (Level 2) Measured: open findings in CWE-613.', 'automatic'),
    ('V7.4', 'Session Termination', 'Section-level attestation for V7.4.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V7.4.1', 'When session termination is triggered (such as logout or expiration), the…', 'Verify that when session termination is triggered (such as logout or expiration), the application disallows any further use of the session. For reference tokens or stateful sessions, this means invalidating the session data at the application backend. Applications using self-contained tokens will need a solution such as maintaining a list of terminated tokens, disallowing tokens produced before a per-user date and time or rotating a per-user signing key. (Level 1) Measured: open findings in CWE-613.', 'automatic'),
    ('V7.4.2', 'Application terminates all active sessions when a user account is disabled or…', 'Verify that the application terminates all active sessions when a user account is disabled or deleted (such as an employee leaving the company). (Level 1) Measured: open findings in CWE-613.', 'automatic'),
    ('V7.4.3', 'Application gives the option to terminate all other active sessions after a…', 'Verify that the application gives the option to terminate all other active sessions after a successful change or removal of any authentication factor (including password change via reset or recovery and, if present, an MFA settings update). (Level 2) Measured: open findings in CWE-613.', 'automatic'),
    ('V7.4.5', 'Application administrators are able to terminate active sessions for an…', 'Verify that application administrators are able to terminate active sessions for an individual user or for all users. (Level 2) Measured: open findings in CWE-613.', 'automatic'),
    ('V7.5', 'Defenses Against Session Abuse', 'Section-level attestation for V7.5.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V7.5.1', 'Application requires full re-authentication before allowing modifications to…', 'Verify that the application requires full re-authentication before allowing modifications to sensitive account attributes which may affect authentication such as email address, phone number, MFA configuration, or other information used in account recovery. (Level 2) Measured: open findings in CWE-306.', 'automatic'),
    ('V7.5.3', 'Application requires further authentication with at least one factor or…', 'Verify that the application requires further authentication with at least one factor or secondary verification before performing highly sensitive transactions or operations. (Level 3) Measured: open findings in CWE-306.', 'automatic'),
    ('V7.6', 'Federated Re-authentication', 'Section-level attestation for V7.6.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V7.6.1', 'Session lifetime and termination between Relying Parties (RPs) and Identity…', 'Verify that session lifetime and termination between Relying Parties (RPs) and Identity Providers (IdPs) behave as documented, requiring re-authentication as necessary such as when the maximum time between IdP authentication events is reached. (Level 2) Measured: open findings in CWE-613.', 'automatic'),
    ('V8.1', 'Authorization Documentation', 'Section-level attestation for V8.1.1, V8.1.2, V8.1.3, V8.1.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V8.2', 'General Authorization Design', 'Section-level attestation for V8.2.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V8.2.1', 'Application ensures that function-level access is restricted to consumers with…', 'Verify that the application ensures that function-level access is restricted to consumers with explicit permissions. (Level 1) Measured: open findings in CWE-285, CWE-862, CWE-863.', 'automatic'),
    ('V8.2.2', 'Application ensures that data-specific access is restricted to consumers with…', 'Verify that the application ensures that data-specific access is restricted to consumers with explicit permissions to specific data items to mitigate insecure direct object reference (IDOR) and broken object level authorization (BOLA). (Level 1) Measured: open findings in CWE-639.', 'automatic'),
    ('V8.2.3', 'Application ensures that field-level access is restricted to consumers with…', 'Verify that the application ensures that field-level access is restricted to consumers with explicit permissions to specific fields to mitigate broken object property level authorization (BOPLA). (Level 2) Measured: open findings in CWE-283.', 'automatic'),
    ('V8.3', 'Operation Level Authorization', 'Section-level attestation for V8.3.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V8.3.1', 'Application enforces authorization rules at a trusted service layer and…', 'Verify that the application enforces authorization rules at a trusted service layer and doesn''t rely on controls that an untrusted consumer could manipulate, such as client-side JavaScript. (Level 1) Measured: open findings in CWE-602.', 'automatic'),
    ('V8.3.3', 'Access to an object is based on the originating subject''s (e.g', 'Verify that access to an object is based on the originating subject''s (e.g. consumer''s) permissions, not on the permissions of any intermediary or service acting on their behalf. For example, if a consumer calls a web service using a self-contained token for authentication, and the service then requests data from a different service, the second service will use the consumer''s token, rather than a machine-to-machine token from the first service, to make permission decisions. (Level 3) Measured: open findings in CWE-441.', 'automatic'),
    ('V8.4.1', 'Multi-tenant applications use cross-tenant controls to ensure consumer…', 'Verify that multi-tenant applications use cross-tenant controls to ensure consumer operations will never affect tenants with which they do not have permissions to interact. (Level 2) Measured: open findings in CWE-283.', 'automatic'),
    ('V8.4.2', 'Access to administrative interfaces incorporates multiple layers of security…', 'Verify that access to administrative interfaces incorporates multiple layers of security, including continuous consumer identity verification, device security posture assessment, and contextual risk analysis, ensuring that network location or trusted endpoints are not the sole factors for authorization even though they may reduce the likelihood of unauthorized access. (Level 3) Measured: open findings in CWE-419.', 'automatic'),
    ('V9.1', 'Token source and integrity', 'Section-level attestation for V9.1.3 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V9.1.1', 'Self-contained tokens are validated using their digital signature or MAC to…', 'Verify that self-contained tokens are validated using their digital signature or MAC to protect against tampering before accepting the token''s contents. (Level 1) Measured: open findings in CWE-345.', 'automatic'),
    ('V9.1.2', 'Only algorithms on an allowlist can be used to create and verify…', 'Verify that only algorithms on an allowlist can be used to create and verify self-contained tokens, for a given context. The allowlist must include the permitted algorithms, ideally only either symmetric or asymmetric algorithms, and must not include the ''None'' algorithm. If both symmetric and asymmetric must be supported, additional controls will be needed to prevent key confusion. (Level 1) Measured: open findings in CWE-757.', 'automatic'),
    ('V9.2', 'Token content', 'Section-level attestation for V9.2.2, V9.2.3, V9.2.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V9.2.1', 'If a validity time span is present in the token data, the token and its…', 'Verify that, if a validity time span is present in the token data, the token and its content are accepted only if the verification time is within this validity time span. For example, for JWTs, the claims ''nbf'' and ''exp'' must be verified. (Level 1) Measured: open findings in CWE-613.', 'automatic'),
    ('V10.1', 'Generic OAuth and OIDC Security', 'Section-level attestation for V10.1.1, V10.1.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V10.2', 'OAuth Client', 'Section-level attestation for V10.2.1, V10.2.2, V10.2.3 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V10.3', 'OAuth Resource Server', 'Section-level attestation for V10.3.1, V10.3.2, V10.3.3, V10.3.4, V10.3.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V10.4', 'OAuth Authorization Server', 'Section-level attestation for V10.4.1, V10.4.2, V10.4.3, V10.4.4, V10.4.5, V10.4.6, V10.4.7, V10.4.8, V10.4.9, V10.4.10, V10.4.11, V10.4.12, V10.4.13, V10.4.14, V10.4.15, V10.4.16 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V10.5', 'OIDC Client', 'Section-level attestation for V10.5.1, V10.5.2, V10.5.3, V10.5.4, V10.5.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V10.6', 'OpenID Provider', 'Section-level attestation for V10.6.1, V10.6.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V10.7', 'Consent Management', 'Section-level attestation for V10.7.1, V10.7.2, V10.7.3 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V11.1', 'Cryptographic Inventory and Documentation', 'Section-level attestation for V11.1.1, V11.1.2, V11.1.3, V11.1.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V11.2.1', 'Industry-validated implementations (including libraries and…', 'Verify that industry-validated implementations (including libraries and hardware-accelerated implementations) are used for cryptographic operations. (Level 2) Measured: open findings in CWE-327.', 'automatic'),
    ('V11.2.2', 'Application is designed with crypto agility such that random number…', 'Verify that the application is designed with crypto agility such that random number, authenticated encryption, MAC, or hashing algorithms, key lengths, rounds, ciphers and modes can be reconfigured, upgraded, or swapped at any time, to protect against cryptographic breaks. Similarly, it must also be possible to replace keys and passwords and re-encrypt data. This will allow for seamless upgrades to post-quantum cryptography (PQC), once high-assurance implementations of approved PQC schemes or standards are widely available. (Level 2) Measured: open findings in CWE-320.', 'automatic'),
    ('V11.2.3', 'All cryptographic primitives utilize a minimum of 128-bits of security based…', 'Verify that all cryptographic primitives utilize a minimum of 128-bits of security based on the algorithm, key size, and configuration. For example, a 256-bit ECC key provides roughly 128 bits of security where RSA requires a 3072-bit key to achieve 128 bits of security. (Level 2) Measured: open findings in CWE-311.', 'automatic'),
    ('V11.2.4', 'All cryptographic operations are constant-time, with no ''short-circuit''…', 'Verify that all cryptographic operations are constant-time, with no ''short-circuit'' operations in comparisons, calculations, or returns, to avoid leaking information. (Level 3) Measured: open findings in CWE-385.', 'automatic'),
    ('V11.2.5', 'All cryptographic modules fail securely, and errors are handled in a way that…', 'Verify that all cryptographic modules fail securely, and errors are handled in a way that does not enable vulnerabilities, such as Padding Oracle attacks. (Level 3) Measured: open findings in CWE-310.', 'automatic'),
    ('V11.3.1', 'Insecure block modes (e.g., ECB) and weak padding schemes (e.g., PKCS#1 v1.5)…', 'Verify that insecure block modes (e.g., ECB) and weak padding schemes (e.g., PKCS#1 v1.5) are not used. (Level 1) Measured: open findings in CWE-326.', 'automatic'),
    ('V11.3.2', 'Only approved ciphers and modes such as AES with GCM are used', 'Verify that only approved ciphers and modes such as AES with GCM are used. (Level 1) Measured: open findings in CWE-326.', 'automatic'),
    ('V11.3.3', 'Encrypted data is protected against unauthorized modification preferably by…', 'Verify that encrypted data is protected against unauthorized modification preferably by using an approved authenticated encryption method or by combining an approved encryption method with an approved MAC algorithm. (Level 2) Measured: open findings in CWE-326.', 'automatic'),
    ('V11.3.4', 'Nonces, initialization vectors, and other single-use numbers are not used for…', 'Verify that nonces, initialization vectors, and other single-use numbers are not used for more than one encryption key and data-element pair. The method of generation must be appropriate for the algorithm being used. (Level 3) Measured: open findings in CWE-326.', 'automatic'),
    ('V11.3.5', 'Any combination of an encryption algorithm and a MAC algorithm is operating in…', 'Verify that any combination of an encryption algorithm and a MAC algorithm is operating in encrypt-then-MAC mode. (Level 3) Measured: open findings in CWE-326.', 'automatic'),
    ('V11.4', 'Hashing and Hash-based Functions', 'Section-level attestation for V11.4.3, V11.4.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V11.4.1', 'Only approved hash functions are used for general cryptographic use cases…', 'Verify that only approved hash functions are used for general cryptographic use cases, including digital signatures, HMAC, KDF, and random bit generation. Disallowed hash functions, such as MD5, must not be used for any cryptographic purpose. (Level 1) Measured: open findings in CWE-327, CWE-328.', 'automatic'),
    ('V11.4.2', 'Passwords are stored using an approved, computationally intensive, key…', 'Verify that passwords are stored using an approved, computationally intensive, key derivation function (also known as a "password hashing function"), with parameter settings configured based on current guidance. The settings should balance security and performance to make brute-force attacks sufficiently challenging for the required level of security. (Level 2) Measured: open findings in CWE-759, CWE-760, CWE-916.', 'automatic'),
    ('V11.5.1', 'All random numbers and strings which are intended to be non-guessable must be…', 'Verify that all random numbers and strings which are intended to be non-guessable must be generated using a cryptographically secure pseudo-random number generator (CSPRNG) and have at least 128 bits of entropy. Note that UUIDs do not respect this condition. (Level 2) Measured: open findings in CWE-338.', 'automatic'),
    ('V11.5.2', 'Random number generation mechanism in use is designed to work securely, even…', 'Verify that the random number generation mechanism in use is designed to work securely, even under heavy demand. (Level 3) Measured: open findings in CWE-338.', 'automatic'),
    ('V11.6', 'Public Key Cryptography', 'Section-level attestation for V11.6.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V11.6.1', 'Only approved cryptographic algorithms and modes of operation are used for key…', 'Verify that only approved cryptographic algorithms and modes of operation are used for key generation and seeding, and digital signature generation and verification. Key generation algorithms must not generate insecure keys vulnerable to known attacks, for example, RSA keys which are vulnerable to Fermat factorization. (Level 2) Measured: open findings in CWE-327.', 'automatic'),
    ('V11.7', 'In-Use Data Cryptography', 'Section-level attestation for V11.7.1, V11.7.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V12.1', 'General TLS Security Guidance', 'Section-level attestation for V12.1.3, V12.1.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V12.1.1', 'Only the latest recommended versions of the TLS protocol are enabled, such as…', 'Verify that only the latest recommended versions of the TLS protocol are enabled, such as TLS 1.2 and TLS 1.3. The latest version of the TLS protocol must be the preferred option. (Level 1) Measured: open findings in CWE-326.', 'automatic'),
    ('V12.1.2', 'Only recommended cipher suites are enabled, with the strongest cipher suites…', 'Verify that only recommended cipher suites are enabled, with the strongest cipher suites set as preferred. L3 applications must only support cipher suites which provide forward secrecy. (Level 2) Measured: open findings in CWE-326.', 'automatic'),
    ('V12.1.4', 'Proper certification revocation, such as Online Certificate Status Protocol…', 'Verify that proper certification revocation, such as Online Certificate Status Protocol (OCSP) Stapling, is enabled and configured. (Level 3) Measured: open findings in CWE-299.', 'automatic'),
    ('V12.2.1', 'TLS is used for all connectivity between a client and external facing…', 'Verify that TLS is used for all connectivity between a client and external facing, HTTP-based services, and does not fall back to insecure or unencrypted communications. (Level 1) Measured: open findings in CWE-319.', 'automatic'),
    ('V12.2.2', 'External facing services use publicly trusted TLS certificates', 'Verify that external facing services use publicly trusted TLS certificates. (Level 1) Measured: open findings in CWE-295.', 'automatic'),
    ('V12.3', 'General Service to Service Communication Security', 'Section-level attestation for V12.3.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V12.3.1', 'An encrypted protocol such as TLS is used for all inbound and outbound…', 'Verify that an encrypted protocol such as TLS is used for all inbound and outbound connections to and from the application, including monitoring systems, management tools, remote access and SSH, middleware, databases, mainframes, partner systems, or external APIs. The server must not fall back to insecure or unencrypted protocols. (Level 2) Measured: open findings in CWE-319.', 'automatic'),
    ('V12.3.3', 'TLS or another appropriate transport encryption mechanism used for all…', 'Verify that TLS or another appropriate transport encryption mechanism used for all connectivity between internal, HTTP-based services within the application, and does not fall back to insecure or unencrypted communications. (Level 2) Measured: open findings in CWE-319.', 'automatic'),
    ('V12.3.4', 'TLS connections between internal services use trusted certificates', 'Verify that TLS connections between internal services use trusted certificates. Where internally generated or self-signed certificates are used, the consuming service must be configured to only trust specific internal CAs and specific self-signed certificates. (Level 2) Measured: open findings in CWE-295.', 'automatic'),
    ('V12.3.5', 'Services communicating internally within a system (intra-service…', 'Verify that services communicating internally within a system (intra-service communications) use strong authentication to ensure that each endpoint is verified. Strong authentication methods, such as TLS client authentication, must be employed to ensure identity, using public-key infrastructure and mechanisms that are resistant to replay attacks. For microservice architectures, consider using a service mesh to simplify certificate management and enhance security. (Level 3) Measured: open findings in CWE-295.', 'automatic'),
    ('V13.1', 'Configuration Documentation', 'Section-level attestation for V13.1.1, V13.1.2, V13.1.3, V13.1.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V13.2', 'Backend Communication Configuration', 'Section-level attestation for V13.2.6 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V13.2.1', 'Communications between backend application components that don''t support the…', 'Verify that communications between backend application components that don''t support the application''s standard user session mechanism, including APIs, middleware, and data layers, are authenticated. Authentication must use individual service accounts, short-term tokens, or certificate-based authentication and not unchanging credentials such as passwords, API keys, or shared accounts with privileged access. (Level 2) Measured: open findings in CWE-287.', 'automatic'),
    ('V13.2.2', 'Communications between backend application components, including local or…', 'Verify that communications between backend application components, including local or operating system services, APIs, middleware, and data layers, are performed with accounts assigned the least necessary privileges. (Level 2) Measured: open findings in CWE-272.', 'automatic'),
    ('V13.2.3', 'If a credential has to be used for service authentication, the credential…', 'Verify that if a credential has to be used for service authentication, the credential being used by the consumer is not a default credential (e.g., root/root or admin/admin). (Level 2) Measured: open findings in CWE-255.', 'automatic'),
    ('V13.2.4', 'An allowlist is used to define the external resources or systems with which…', 'Verify that an allowlist is used to define the external resources or systems with which the application is permitted to communicate (e.g., for outbound requests, data loads, or file access). This allowlist can be implemented at the application layer, web server, firewall, or a combination of different layers. (Level 2) Measured: open findings in CWE-732.', 'automatic'),
    ('V13.2.5', 'Web or application server is configured with an allowlist of resources or…', 'Verify that the web or application server is configured with an allowlist of resources or systems to which the server can send requests or load data or files from. (Level 2) Measured: open findings in CWE-918.', 'automatic'),
    ('V13.3.1', 'A secrets management solution, such as a key vault, is used to securely…', 'Verify that a secrets management solution, such as a key vault, is used to securely create, store, control access to, and destroy backend secrets. These could include passwords, key material, integrations with databases and third-party systems, keys and seeds for time-based tokens, other internal secrets, and API keys. Secrets must not be included in application source code or included in build artifacts. For an L3 application, this must involve a hardware-backed solution such as an HSM. (Level 2) Measured: open findings in CWE-798; open secret findings; failing Checkov/Trivy checks.', 'automatic'),
    ('V13.3.2', 'Access to secret assets adheres to the principle of least privilege', 'Verify that access to secret assets adheres to the principle of least privilege. (Level 2) Measured: open findings in CWE-320.', 'automatic'),
    ('V13.3.3', 'All cryptographic operations are performed using an isolated security module…', 'Verify that all cryptographic operations are performed using an isolated security module (such as a vault or hardware security module) to securely manage and protect key material from exposure outside of the security module. (Level 3) Measured: open findings in CWE-320.', 'automatic'),
    ('V13.3.4', 'Secrets are configured to expire and be rotated based on the application''s…', 'Verify that secrets are configured to expire and be rotated based on the application''s documentation. (Level 3) Measured: open findings in CWE-320.', 'automatic'),
    ('V13.4', 'Unintended Information Leakage', 'Section-level attestation for V13.4.1 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V13.4.2', 'Debug modes are disabled for all components in production environments to…', 'Verify that debug modes are disabled for all components in production environments to prevent exposure of debugging features and information leakage. (Level 2) Measured: open findings in CWE-497.', 'automatic'),
    ('V13.4.3', 'Web servers do not expose directory listings to clients unless explicitly…', 'Verify that web servers do not expose directory listings to clients unless explicitly intended. (Level 2) Measured: open findings in CWE-548.', 'automatic'),
    ('V13.4.4', 'Using the HTTP TRACE method is not supported in production environments, to…', 'Verify that using the HTTP TRACE method is not supported in production environments, to avoid potential information leakage. (Level 2) Measured: open findings in CWE-749.', 'automatic'),
    ('V13.4.5', 'Documentation (such as for internal APIs) and monitoring endpoints are not…', 'Verify that documentation (such as for internal APIs) and monitoring endpoints are not exposed unless explicitly intended. (Level 2) Measured: open findings in CWE-1002.', 'automatic'),
    ('V13.4.6', 'Application does not expose detailed version information of backend components', 'Verify that the application does not expose detailed version information of backend components. (Level 3) Measured: open findings in CWE-200.', 'automatic'),
    ('V13.4.7', 'Web tier is configured to only serve files with specific file extensions to…', 'Verify that the web tier is configured to only serve files with specific file extensions to prevent unintentional information, configuration, and source code leakage. (Level 3) Measured: open findings in CWE-552.', 'automatic'),
    ('V14.1', 'Data Protection Documentation', 'Section-level attestation for V14.1.1, V14.1.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V14.2', 'General Data Protection', 'Section-level attestation for V14.2.4, V14.2.6, V14.2.7 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V14.2.1', 'Sensitive data is only sent to the server in the HTTP message body or header…', 'Verify that sensitive data is only sent to the server in the HTTP message body or header fields, and that the URL and query string do not contain sensitive information, such as an API key or session token. (Level 1) Measured: open findings in CWE-598.', 'automatic'),
    ('V14.2.2', 'Application prevents sensitive data from being cached in server components…', 'Verify that the application prevents sensitive data from being cached in server components, such as load balancers and application caches, or ensures that the data is securely purged after use. (Level 2) Measured: open findings in CWE-524.', 'automatic'),
    ('V14.2.3', 'Defined sensitive data is not sent to untrusted parties (e.g., user trackers)…', 'Verify that defined sensitive data is not sent to untrusted parties (e.g., user trackers) to prevent unwanted collection of data outside of the application''s control. (Level 2) Measured: open findings in CWE-200.', 'automatic'),
    ('V14.2.5', 'Caching mechanisms are configured to only cache responses which have the…', 'Verify that caching mechanisms are configured to only cache responses which have the expected content type for that resource and do not contain sensitive, dynamic content. The web server should return a 404 or 302 response when a non-existent file is accessed rather than returning a different, valid file. This should prevent Web Cache Deception attacks. (Level 3) Measured: open findings in CWE-444.', 'automatic'),
    ('V14.2.8', 'Sensitive information is removed from the metadata of user-submitted files…', 'Verify that sensitive information is removed from the metadata of user-submitted files unless storage is consented to by the user. (Level 3) Measured: open findings in CWE-212.', 'automatic'),
    ('V14.3.1', 'Authenticated data is cleared from client storage, such as the browser DOM…', 'Verify that authenticated data is cleared from client storage, such as the browser DOM, after the client or session is terminated. The ''Clear-Site-Data'' HTTP response header field may be able to help with this but the client-side should also be able to clear up if the server connection is not available when the session is terminated. (Level 1) Measured: open findings in CWE-922.', 'automatic'),
    ('V14.3.2', 'Application sets sufficient anti-caching HTTP response header fields (i.e.…', 'Verify that the application sets sufficient anti-caching HTTP response header fields (i.e., Cache-Control: no-store) so that sensitive data is not cached in browsers. (Level 2) Measured: open findings in CWE-525.', 'automatic'),
    ('V14.3.3', 'Data stored in browser storage (such as localStorage, sessionStorage…', 'Verify that data stored in browser storage (such as localStorage, sessionStorage, IndexedDB, or cookies) does not contain sensitive data, with the exception of session tokens. (Level 2) Measured: open findings in CWE-922.', 'automatic'),
    ('V15.1', 'Secure Coding and Architecture Documentation', 'Section-level attestation for V15.1.1, V15.1.3, V15.1.4, V15.1.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V15.1.2', 'An inventory catalog, such as software bill of materials (SBOM), is maintained…', 'Verify that an inventory catalog, such as software bill of materials (SBOM), is maintained of all third-party libraries in use, including verifying that components come from pre-defined, trusted, and continually maintained repositories. (Level 2) Measured: an SBOM on the default branch.', 'automatic'),
    ('V15.2', 'Security Architecture and Dependencies', 'Section-level attestation for V15.2.2, V15.2.3, V15.2.5 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V15.2.1', 'Application only contains components which have not breached the documented…', 'Verify that the application only contains components which have not breached the documented update and remediation time frames. (Level 1) Measured: open findings past their remediation SLA.', 'automatic'),
    ('V15.2.4', 'Third-party components and all of their transitive dependencies are included…', 'Verify that third-party components and all of their transitive dependencies are included from the expected repository, whether internally owned or an external source, and that there is no risk of a dependency confusion attack. (Level 3) Measured: open findings in CWE-427.', 'automatic'),
    ('V15.3', 'Defensive Coding', 'Section-level attestation for V15.3.1, V15.3.2, V15.3.6 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V15.3.3', 'Application has countermeasures to protect against mass assignment attacks by…', 'Verify that the application has countermeasures to protect against mass assignment attacks by limiting allowed fields per controller and action, e.g., it is not possible to insert or update a field value when it was not intended to be part of that action. (Level 2) Measured: open findings in CWE-915.', 'automatic'),
    ('V15.3.4', 'All proxying and middleware components transfer the user''s original IP address…', 'Verify that all proxying and middleware components transfer the user''s original IP address correctly using trusted data fields that cannot be manipulated by the end user, and the application and web server use this correct value for logging and security decisions such as rate limiting, taking into account that even the original IP address may not be reliable due to dynamic IPs, VPNs, or corporate firewalls. (Level 2) Measured: open findings in CWE-348.', 'automatic'),
    ('V15.3.5', 'Application explicitly ensures that variables are of the correct type and…', 'Verify that the application explicitly ensures that variables are of the correct type and performs strict equality and comparator operations. This is to avoid type juggling or type confusion vulnerabilities caused by the application code making an assumption about a variable type. (Level 2) Measured: open findings in CWE-843.', 'automatic'),
    ('V15.3.7', 'Application has defenses against HTTP parameter pollution attacks…', 'Verify that the application has defenses against HTTP parameter pollution attacks, particularly if the application framework makes no distinction about the source of request parameters (query string, body parameters, cookies, or header fields). (Level 2) Measured: open findings in CWE-235.', 'automatic'),
    ('V15.4.1', 'Shared objects in multi-threaded code (such as caches, files, or in-memory…', 'Verify that shared objects in multi-threaded code (such as caches, files, or in-memory objects accessed by multiple threads) are accessed safely by using thread-safe types and synchronization mechanisms like locks or semaphores to avoid race conditions and data corruption. (Level 3) Measured: open findings in CWE-362.', 'automatic'),
    ('V15.4.2', 'Checks on a resource''s state, such as its existence or permissions, and the…', 'Verify that checks on a resource''s state, such as its existence or permissions, and the actions that depend on them are performed as a single atomic operation to prevent time-of-check to time-of-use (TOCTOU) race conditions. For example, checking if a file exists before opening it, or verifying a user’s access before granting it. (Level 3) Measured: open findings in CWE-367.', 'automatic'),
    ('V15.4.3', 'Locks are used consistently to avoid threads getting stuck, whether by waiting…', 'Verify that locks are used consistently to avoid threads getting stuck, whether by waiting on each other or retrying endlessly, and that locking logic stays within the code responsible for managing the resource to ensure locks cannot be inadvertently or maliciously modified by external classes or code. (Level 3) Measured: open findings in CWE-833.', 'automatic'),
    ('V15.4.4', 'Resource allocation policies prevent thread starvation by ensuring fair access…', 'Verify that resource allocation policies prevent thread starvation by ensuring fair access to resources, such as by leveraging thread pools, allowing lower-priority threads to proceed within a reasonable timeframe. (Level 3) Measured: open findings in CWE-410.', 'automatic'),
    ('V16.1', 'Security Logging Documentation', 'Section-level attestation for V16.1.1 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V16.2', 'General Logging', 'Section-level attestation for V16.2.2, V16.2.3, V16.2.4 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V16.2.1', 'Each log entry includes necessary metadata (such as when, where, who, what)…', 'Verify that each log entry includes necessary metadata (such as when, where, who, what) that would allow for a detailed investigation of the timeline when an event happens. (Level 2) Measured: open findings in CWE-778.', 'automatic'),
    ('V16.2.5', 'When logging sensitive data, the application enforces logging based on the…', 'Verify that when logging sensitive data, the application enforces logging based on the data''s protection level. For example, it may not be allowed to log certain data, such as credentials or payment details. Other data, such as session tokens, may only be logged by being hashed or masked, either in full or partially. (Level 2) Measured: open findings in CWE-532.', 'automatic'),
    ('V16.3.1', 'All authentication operations are logged, including successful and…', 'Verify that all authentication operations are logged, including successful and unsuccessful attempts. Additional metadata, such as the type of authentication or factors used, should also be collected. (Level 2) Measured: open findings in CWE-778.', 'automatic'),
    ('V16.3.2', 'Failed authorization attempts are logged', 'Verify that failed authorization attempts are logged. For L3, this must include logging all authorization decisions, including logging when sensitive data is accessed (without logging the sensitive data itself). (Level 2) Measured: open findings in CWE-285.', 'automatic'),
    ('V16.3.3', 'Application logs the security events that are defined in the documentation and…', 'Verify that the application logs the security events that are defined in the documentation and also logs attempts to bypass the security controls, such as input validation, business logic, and anti-automation. (Level 2) Measured: open findings in CWE-778.', 'automatic'),
    ('V16.3.4', 'Application logs unexpected errors and security control failures such as…', 'Verify that the application logs unexpected errors and security control failures such as backend TLS failures. (Level 2) Measured: open findings in CWE-778.', 'automatic'),
    ('V16.4', 'Log Protection', 'Section-level attestation for V16.4.3 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V16.4.1', 'All logging components appropriately encode data to prevent log injection', 'Verify that all logging components appropriately encode data to prevent log injection. (Level 2) Measured: open findings in CWE-117.', 'automatic'),
    ('V16.4.2', 'Logs are protected from unauthorized access and cannot be modified', 'Verify that logs are protected from unauthorized access and cannot be modified. (Level 2) Measured: open findings in CWE-200.', 'automatic'),
    ('V16.5', 'Error Handling', 'Section-level attestation for V16.5.2, V16.5.3 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V16.5.1', 'A generic message is returned to the consumer when an unexpected or…', 'Verify that a generic message is returned to the consumer when an unexpected or security-sensitive error occurs, ensuring no exposure of sensitive internal system data such as stack traces, queries, secret keys, and tokens. (Level 2) Measured: open findings in CWE-209, CWE-210.', 'automatic'),
    ('V16.5.4', 'A "last resort" error handler is defined which will catch all unhandled…', 'Verify that a "last resort" error handler is defined which will catch all unhandled exceptions. This is both to avoid losing error details that must go to log files and to ensure that an error does not take down the entire application process, leading to a loss of availability. (Level 3) Measured: open findings in CWE-431.', 'automatic'),
    ('V17.1', 'TURN Server', 'Section-level attestation for V17.1.1, V17.1.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V17.2', 'Media', 'Section-level attestation for V17.2.1, V17.2.2, V17.2.3, V17.2.4, V17.2.5, V17.2.6, V17.2.7, V17.2.8 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual'),
    ('V17.3', 'Signaling', 'Section-level attestation for V17.3.1, V17.3.2 (no CWE-measurable signal). Not measurable by a scan: attest how it is met.', 'manual')
) AS v(code, title, description, assessment)
WHERE fw.key = 'owasp-asvs-5.0';

